-- The Hall adds exactly one Culture to the inherited Barracks yields.
UPDATE Building_YieldChanges SET Yield=Yield+1 WHERE BuildingType='BUILDING_TRI_HALL_OF_TRIUMPHS' AND YieldType='YIELD_CULTURE';
 SELECT 'BUILDING_TRI_HALL_OF_TRIUMPHS','YIELD_CULTURE',1 WHERE NOT EXISTS
 (SELECT 1 FROM Building_YieldChanges WHERE BuildingType='BUILDING_TRI_HALL_OF_TRIUMPHS' AND YieldType='YIELD_CULTURE');
 VALUES ('PROMOTION_TRI_UNBROKEN_ADVANCE','TXT_KEY_TRI_ADVANCE','TXT_KEY_TRI_ADVANCE_HELP',10,0,0,1,1,0,'TRI_OBJECT_ATLAS','PEDIA_ATTRIBUTES','TXT_KEY_TRI_ADVANCE');
 VALUES ('PROMOTION_TRI_VICTORIOUS_MARCH','TXT_KEY_TRI_MARCH','TXT_KEY_TRI_MARCH_HELP',1,1,1,1,1,0,'TRI_OBJECT_ATLAS','PEDIA_ATTRIBUTES','TXT_KEY_TRI_MARCH');
